import {voiceIndex} from './voice-index.js?v=17';
const clip=(id,key,gap)=>{const group=voiceIndex[id],range=group?.segments?.[key];return range?{src:group.src,start:range[0],end:range[1],gap}:null;};
export function guideClips(id,section='intro',step=0){if(section==='intro')return ['heading','step0','step1','step2'].map(key=>clip(id,key,.14)).filter(Boolean);return [clip(id,section==='coach'?'step'+step:section,.1)].filter(Boolean);}
const digit=['không','một','hai','ba','bốn','năm','sáu','bảy','tám','chín'];
function integerWords(value,full=false){const n=Math.floor(value);if(n===0)return full?[]:['không'];if(n>=1000){const scale=n>=1e9?1e9:n>=1e6?1e6:1000,name=scale===1e9?'tỷ':scale===1e6?'triệu':'nghìn';return [...integerWords(Math.floor(n/scale)),name,...(n%scale?integerWords(n%scale,true):[])];}const result=[],hundreds=Math.floor(n/100),tens=Math.floor(n/10)%10,ones=n%10;if(hundreds||full)result.push(digit[hundreds],'trăm');if(tens>1)result.push(digit[tens],'mươi');else if(tens===1)result.push('mười');else if(ones&&(hundreds||full))result.push('lẻ');if(ones)result.push(ones===1&&tens>1?'mốt':ones===5&&tens>0?'lăm':digit[ones]);return result;}
export function numberWords(display){let str=String(display).replaceAll('.','').replace('−','-');if(!/^[-+]?\d+(?:,\d+)?(?:e[-+]?\d+)?$/i.test(str))return ['chưa xác định'];const [mantissa,exponent]=str.toLowerCase().split('e'),negative=mantissa.startsWith('-'),[whole,decimal]=mantissa.replace(/^[-+]/,'').split(','),words=[...(negative?['âm']:[]),...integerWords(+whole),...(decimal?['phẩy',...[...decimal].map(n=>digit[+n])]:[])];if(exponent!==undefined)words.push('nhân','mười','mũ',...(exponent.startsWith('-')?['âm']:[]),...integerWords(Math.abs(+exponent)));return words;}
export function readoutClips(id,readings){return readings.flatMap(reading=>{const label=clip(id,'label-'+reading.key,.08),words=numberWords(reading.display).map(word=>clip('common','word-'+word,.015)),unit=reading.display==='—'?null:clip('common','unit-'+reading.unit,.12);return [label,...words,unit].filter(Boolean);});}
export function previewClips(){return [clip('common','preview')].filter(Boolean);}
